                ndp1 = [INF] * (L + 1)
                ch = 0 if s[i]=='0' else 1
                for len_ in range(1, L+1):
                    # keep same char
                    if dp0[len_] < INF:
                        if len_ + 1 <= L:
                            ndp0[len_+1] = min(ndp0[len_+1], dp0[len_])
                    if dp1[len_] < INF:
