    children = [[] for _ in range(N)]
    for i, a in enumerate(A):
        children[a].append(i)

    visited = [0] * N  # 0 unvisited, 1 visiting, 2 visited
    cycle_nodes = [False] * N
    stack = []
    cycles = []

    def dfs_cycle(u):
        visited[u] = 1
        stack.append(u)
        v = A[u]
        if visited[v] == 0:
            dfs_cycle(v)
        elif visited[v] == 1:
            # found a cycle
            cyc = []
            while True:
                w = stack.pop()
                cyc.append(w)
                cycle_nodes[w] = True
                if w == v:
                    break
            cycles.append(cyc)
        # backtrack
        if stack and stack[-1] == u:
            stack.pop()
        visited[u] = 2

