        stack = list(cyc)
        while stack:
            u = stack.pop()
            for w in children[u]:
                if comp_id[w] == -1:
                    comp_id[w] = cid
                    stack.append(w)
        cid += 1

    # For nodes not in any cycle (standalone), they form their own component
    for i in range(N):
        if comp_id[i] == -1:
            comp_id[i] = cid
            cid += 1

    # Count tree nodes per component
    tree_counts = [0] * cid
    for i in range(N):
        if not cycle_nodes[i]:
            tree_counts[comp_id[i]] += 1

    # For each component, compute sum_{v=1..M} v^{tree_size}
    ans = 1
    for sz in tree_counts:
        # compute sum of powers
        s = 0
        for v in range(1, M + 1):
            s = (s + mod_pow(v, sz)) % MOD
        ans = ans * s % MOD

    print(ans)

