class Solution:
    MOD = 10**9 + 7
    def countWinningSequences(self, s: str) -> int:
        n = len(s)
        # map 'F','W','E' to 0,1,2
        mp = {'F':0,'W':1,'E':2}
        a_seq = [mp[ch] for ch in s]
        # win pairs for Bob: (bob,alice)
        win_pairs = {(0,2),(1,0),(2,1)}
        offset = n
        # dp[pos][last][diff+offset]
        dp = [[[0]*(2*n+1) for _ in range(3)] for _ in range(n+1)]
        # init pos=0, no last, but we can start with any first move
        for b in range(3):
            # compute diff for first round
            a = a_seq[0]
            if b==a:
                diff=0
            elif (b,a) in win_pairs:
                diff=1
            else:
                diff=-1
            dp[1][b][diff+offset] = 1
        for pos in range(1,n):
            for last in range(3):
                for d in range(2*n+1):
                    cnt = dp[pos][last][d]
                    if not cnt: continue
                    for b in range(3):
                        if b==last: continue
                        a = a_seq[pos]
                        if b==a:
                            nd=0
                        elif (b,a) in win_pairs:
                            nd=1
                        else:
                            nd=-1
                        ndiff = (d-offset)+nd
                        if 0<=ndiff+offset<2*n+1:
                            dp[pos+1][b][ndiff+offset] = (dp[pos+1][b][ndiff+offset]+cnt)%self.MOD
        res=0
        for last in range(3):
            for d in range(offset+1,2*n+1):
                res = (res+dp[n][last][d])%self.MOD
        return res
