        # merge positions
        idx_v = idx_v1 = 0
        last_v = last_v1 = 0
        merged = []
        while idx_v < len(lst_v) or idx_v1 < len(lst_v1):
            if idx_v1 >= len(lst_v1) or (idx_v < len(lst_v) and lst_v[idx_v] < lst_v1[idx_v1]):
                merged.append((lst_v[idx_v], v))
                idx_v += 1
            else:
                merged.append((lst_v1[idx_v1], v + 1))
