        from functools import lru_cache

        odd_nums = [i for i in range(1, n+1) if i % 2]
        even_nums = [i for i in range(1, n+1) if i % 2 == 0]
        total_odd = len(odd_nums)
        total_even = len(even_nums)

        @lru_cache(maxsize=None)
        def dp(rem_odd: int, rem_even: int, last_parity: int) -> int:
            if rem_odd == 0 and rem_even == 0:
                return 1
            total = 0
            if last_parity == -1 or last_parity == 0:  # need odd
                if rem_odd > 0:
                    total += rem_odd * dp(rem_odd-1, rem_even, 1)
            if last_parity == -1 or last_parity == 1:  # need even
                if rem_even > 0:
                    total += rem_even * dp(rem_odd, rem_even-1, 0)
            return total

        result = []
        rem_odd, rem_even = total_odd, total_even
        last_parity = -1  # none
        for pos in range(n):
            candidates = []
            if rem_odd > 0:
                candidates.extend([i for i in odd_nums if i not in result])
            if rem_even > 0:
                candidates.extend([i for i in even_nums if i not in result])
            candidates.sort()
            chosen = None
            for x in candidates:
                p = x % 2
                if last_parity != -1 and p == last_parity:
                    continue
                if p == 1:
                    cnt = dp(rem_odd-1, rem_even, 1)
                else:
                    cnt = dp(rem_odd, rem_even-1, 0)
                if k > cnt:
                    k -= cnt
                else:
                    chosen = x
                    result.append(x)
                    if p == 1:
                        rem_odd -= 1
                    else:
                        rem_even -= 1
                    last_parity = p
                    break
            if chosen is None:
                return []
        return result

