        odds = [i for i in range(1, n + 1) if i % 2 == 1]
        evens = [i for i in range(1, n + 1) if i % 2 == 0]

        @lru_cache(None)
        def patterns(a: int, b: int, prev: int) -> int:
            if a == 0 and b == 0:
                return 1
            total = 0
            if prev == 0:  # previous even, next must be odd
                if a > 0:
