    size = [1] * (N + 1)
    color = [i for i in range(N + 1)]
    cnt = [0] * (N + 1)
    for i in range(1, N + 1):
        cnt[i] = 1

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a: int, b: int) -> None:
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        ca, cb = color[ra], color[rb]
        # adjust counts if same color
        if ca == cb:
            cnt[ca] -= size[ra] + size[rb]
        if size[ra] < size[rb]:
            ra, rb = rb, ra
            ca, cb = cb, ca
        parent[rb] = ra
        size[ra] += size[rb]
        color[ra] = ca
        if ca == cb:
            cnt[ca] += size[ra]

    out_lines = []
    for _ in range(Q):
        parts = input().split()
