import sys

def hopcroft_karp(adj, n_left, n_right):
    from collections import deque
    pair_u = [-1]*n_left
    pair_v = [-1]*n_right
    dist = [0]*n_left

    def bfs():
        q = deque()
        for u in range(n_left):
            if pair_u[u]==-1:
                dist[u]=0
                q.append(u)
            else:
                dist[u]=-1
        found=False
        while q:
            u=q.popleft()
            for v in adj[u]:
                pu=pair_v[v]
                if pu!=-1 and dist[pu]==-1:
                    dist[pu]=dist[u]+1
                    q.append(pu)
                if pu==-1:
                    found=True
        return found

    def dfs(u):
        for v in adj[u]:
            pu=pair_v[v]
            if pu==-1 or (dist[pu]==dist[u]+1 and dfs(pu)):
                pair_u[u]=v
                pair_v[v]=u
                return True
        dist[u]=-1
        return False

    result=0
    while bfs():
        for u in range(n_left):
            if pair_u[u]==-1 and dfs(u):
                result+=1
    return result

