class Solution:
    def maxSubarrays(self, n: int, conflictingPairs):
        INF = n + 1
        best = [INF] * (n + 2)          # best[start] = minimal end for that start
        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            if b < best[a]:
                best[a] = b

        # Compute contribution for removing each best interval
        total = 0
        # first compute base count (with all intervals)
        cur_min = INF
        for l in range(n, 0, -1):
            if best[l] < cur_min:
                cur_min = best[l]
            if cur_min <= n:
                total += cur_min - l
            else:
                total += n - l + 1

        # Now compute best removal
        cur_min = INF
        prev_min = INF
        prev_l = n + 1
        best_start = -1
        best_end = INF
        best_contrib = 0

        # We'll accumulate contributions for each interval that is best at its start
        best_contribs = [0] * (n + 1)

        for l in range(n, 0, -1):
            if best[l] < cur_min:
                # finalize previous minimal
                if best_start != -1:
                    length = prev_l - l
                    best_contribs[best_start] += (prev_min - cur_min) * length
                # update
                prev_min = cur_min
                cur_min = best[l]
                best_start = l
                prev_l = l
            else:
                prev_l = l

        # finalize last minimal
        if best_start != -1:
            length = prev_l
            best_contribs[best_start] += (prev_min - cur_min) * length

        # Find maximum total
        ans = total
        for s in range(1, n + 1):
            if best[s] != INF:
                cand = total + best_contribs[s]
                if cand > ans:
                    ans = cand
        return ans
