class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        n = len(points)
        # map each point to a position along the perimeter starting from (0,0) clockwise
        pos = []
        for x, y in points:
            if x == 0:
                pos.append(y)  # left edge
            elif y == side:
                pos.append(side + x)  # bottom edge
            elif x == side:
                pos.append(2 * side + (side - y))  # right edge
            else:  # y == 0
                pos.append(3 * side + (side - x))  # top edge
        P = 4 * side
        pos.sort()

        def can(d: int) -> bool:
            # try each point as first
            for start in pos:
                cnt = 1
                last = start
                for _ in range(1, k):
                    # find next point >= last + d (cyclic)
                    target = last + d
                    if target < P:
                        # binary search in pos
                        lo = 0
                        hi = n
                        while lo < hi:
                            mid = (lo + hi) // 2
                            if pos[mid] < target:
                                lo = mid + 1
                            else:
                                hi = mid
                        if lo == n:
                            break
                        nxt = pos[lo]
                    else:
                        # wrap around
                        target -= P
                        lo = 0
                        hi = n
                        while lo < hi:
                            mid = (lo + hi) // 2
                            if pos[mid] < target:
                                lo = mid + 1
                            else:
                                hi = mid
                        if lo == n:
                            break
                        nxt = pos[lo]
                    cnt += 1
                    last = nxt
                    if cnt == k:
                        return True
            return False

        lo, hi = 0, P // 2
        ans = 0
        while lo <= hi:
            mid = (lo + hi) // 2
            if can(mid):
                ans = mid
                lo = mid + 1
            else:
                hi = mid - 1
        return ans
