class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        from functools import lru_cache

        n = len(points)
        # precompute Manhattan distances
        dist = [[abs(points[i][0]-points[j][0])+abs(points[i][1]-points[j][1]) for j in range(n)] for i in range(n)]

        # binary search over possible distance
        lo, hi = 0, 2*side
        def can(d):
            # use backtracking with memoization
            @lru_cache(None)
            def dfs(idx, taken, mask):
                if taken == k:
                    return True
                if idx == n:
                    return False
                # skip remaining if not enough left
                if taken + (n - idx) < k:
                    return False
                # option 1: skip current
                if dfs(idx+1, taken, mask):
                    return True
                # option 2: take current if compatible
                ok = True
                for j in range(n):
                    if (mask>>j)&1:
                        if dist[idx][j] < d:
                            ok = False
                            break
                if ok:
                    if dfs(idx+1, taken+1, mask | (1<<idx)):
                        return True
                return False
            return dfs(0, 0, 0)

        while lo < hi:
            mid = (lo+hi+1)//2
            if can(mid):
                lo = mid
            else:
                hi = mid-1
        return lo
