    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        # Map each boundary point to a 1‑D coordinate along the square perimeter
        L = 4 * side
        t: List[int] = []
        for x, y in points:
            if x == 0:
                t.append(y)
            elif y == side:
                t.append(side + x)
            elif x == side:
                t.append(2 * side + (side - y))
            else:  # y == 0
                t.append(3 * side + (side - x))
        t.sort()

        n = len(t)
        t_ext = t + [x + L for x in t]

        def feasible(d: int) -> bool:
            # try starting from each point on the circle
            for start in range(n):
                cnt = 1
                cur = t_ext[start]
                idx = start + 1
                while cnt < k and idx < start + n:
                    if t_ext[idx] - cur >= d:
                        cur = t_ext[idx]
                        cnt += 1
                    idx += 1
                if cnt == k:
                    return True
            return False

        lo, hi = 0, L
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

