        # check non‑negative requirements
        ok = True
        reqB = Counter()
        for a in knownA:
            val = T - a
            if val < 0:
                ok = False
                break
            reqB[val] += 1
        if not ok:
            continue
        reqA = Counter()
        for b in knownB:
            val = T - b
            if val < 0:
                ok = False
                break
            reqA[val] += 1
        if not ok:
            continue

        # compute needed unknowns
        need_unknownB = 0
        for val, c in reqB.items():
            have = cntB.get(val, 0)
            if c > have:
                need_unknownB += c - have
        if need_unknownB > unknownB:
            continue

        need_unknownA = 0
        for val, c in reqA.items():
            have = cntA.get(val, 0)
            if c > have:
                need_unknownA += c - have
        if need_unknownA > unknownA:
            continue

        print("Yes")
        return
    print("No")

