class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        from functools import lru_cache

        def count_upto(n: int) -> int:
            s = str(n)
            digits = list(map(int, s))
            N = len(digits)

            total = 0
            for target_sum in range(1, 82):  # max possible sum
                @lru_cache(None)
                def dfs(pos: int, cur_sum: int, prod_mod: int, tight: bool) -> int:
                    if cur_sum > target_sum:
                        return 0
                    if pos == N:
                        return int(cur_sum == target_sum and prod_mod % target_sum == 0)
                    limit = digits[pos] if tight else 9
                    res = 0
                    for d in range(0, limit + 1):
                        ntight = tight and d == limit
                        nsum = cur_sum + d
                        nprod_mod = (prod_mod * d) % target_sum if target_sum != 0 else 0
                        res += dfs(pos + 1, nsum, nprod_mod, ntight)
                    return res
                total += dfs(0, 0, 1 % target_sum if target_sum != 0 else 0, True)
            return total

        return count_upto(r) - count_upto(l - 1)
