class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        # Precompute all beautiful numbers without zeros up to 1e9
        self.max_val = 10**9
        self.b_no_zero = []
        def dfs(num, prod, sum_):
            if num > self.max_val:
                return
            if num > 0 and prod % sum_ == 0:
                self.b_no_zero.append(num)
            for d in range(1, 10):
                new_num = num * 10 + d
                if new_num > self.max_val:
                    continue
                dfs(new_num, prod * d, sum_ + d)
        dfs(0, 1, 0)
        self.b_no_zero.sort()
        # Count numbers without zeros in [l,r] using digit DP
        def count_no_zero(n):
            s = str(n)
            from functools import lru_cache
            @lru_cache(None)
            def dp(pos, tight):
                if pos == len(s):
                    return 1
                limit = int(s[pos]) if tight else 9
                res = 0
                for d in range(1, limit+1):
                    if d == 0:
                        continue
                    res += dp(pos+1, tight and d==limit)
                return res
            return dp(0, True)
        total = r - l + 1
        no_zero_r = count_no_zero(r)
        no_zero_l = count_no_zero(l-1)
        no_zero_range = no_zero_r - no_zero_l
        zero_range = total - no_zero_range
        # Count beautiful numbers without zeros in range
        import bisect
        left = bisect.bisect_left(self.b_no_zero, l)
        right = bisect.bisect_right(self.b_no_zero, r)
        beautiful_no_zero = right - left
        return zero_range + beautiful_no_zero
