    stack = []
    for i in range(N-1, -1, -1):
        while stack and H[stack[-1]] <= H[i]:
            stack.pop()
        ng[i] = stack[-1] if stack else None
        stack.append(i)

    LOG = (N+1).bit_length()
    up = [[None]*N for _ in range(LOG)]
    depth = [0]*N
    # compute depth (number of nodes from i to end of chain)
    def dfs(u):
        if ng[u] is None:
            depth[u] = 1
        else:
            if depth[ng[u]] == 0:
                dfs(ng[u])
            depth[u] = depth[ng[u]] + 1
    for i in range(N):
        if depth[i]==0:
            dfs(i)

    for i in range(N):
        up[0][i] = ng[i]
    for k in range(1, LOG):
        for i in range(N):
            prev = up[k-1][i]
            up[k][i] = up[k-1][prev] if prev is not None else None

    # prefix maximum heights along chain from i
    pref_max = [0]*N
    for i in range(N):
        if ng[i] is None:
            pref_max[i] = H[i]
        else:
            pref_max[i] = max(H[i], pref_max[ng[i]])

    out_lines = []
    for _ in range(Q):
        l, r = map(int, input().split())
        l -= 1; r -= 1
        if r == N-1:
            out_lines.append("0")
            continue
        limit = max(H[l], H[r])
        # find last node in chain from r with height <= limit
        cur = r
        if H[cur] > limit:
            # no such node, answer = depth[cur]
            ans = depth[cur]
        else:
            # climb to deepest node with height <= limit
            for k in range(LOG-1, -1, -1):
                nxt = up[k][cur]
                if nxt is not None and H[nxt] <= limit:
                    cur = nxt
            # cur is deepest <= limit
            # next node after cur has height > limit (or None)
            nxt = ng[cur]
            if nxt is None:
                ans = 0
            else:
                ans = depth[nxt]
        out_lines.append(str(ans))
    sys.stdout.write("\n".join(out_lines))

