from collections import deque

def solve() -> None:
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    it = iter(input_data)
    N = int(next(it))
    grid = []
    for _ in range(N):
        line = next(it).strip()
        grid.append(line)

    # adjacency list: for each u, list of (v, label)
    adj = [[] for _ in range(N)]
    for u in range(N):
        for v in range(N):
            c = grid[u][v]
            if c != '-':
                adj[u].append((v, c))

    INF = 10**9
    # result matrix
    ans = [[-1] * N for _ in range(N)]

    # For each start pair (s, t)
    for s in range(N):
        for t in range(N):
            dist = [[INF] * N for _ in range(N)]
            q = deque()
            dist[s][t] = 0
            q.append((s, t))
            best = INF
            while q:
                u, v = q.popleft()
                d = dist[u][v]
                # check finish conditions
                if u == v:
                    if d < best:
                        best = d
                # middle edge from u to v
                if grid[u][v] != '-':
                    if d + 1 < best:
                        best = d + 1
                # expand
