class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        MOD = 10**9 + 7
        # Precompute Stirling numbers of the second kind S[n][k]
        S = [[0] * (n + 1) for _ in range(n + 1)]
        S[0][0] = 1
        for i in range(1, n + 1):
            for k in range(1, i + 1):
                S[i][k] = (S[i-1][k-1] + k * S[i-1][k]) % MOD

        # Precompute factorials up to max(x, n)
        maxv = max(x, n)
        fact = [1] * (maxv + 1)
        for i in range(1, maxv + 1):
            fact[i] = fact[i-1] * i % MOD
        invfact = [1] * (maxv + 1)
        invfact[maxv] = pow(fact[maxv], MOD-2, MOD)
        for i in range(maxv, 0, -1):
            invfact[i-1] = invfact[i] * i % MOD

        def comb(a, b):
            if b < 0 or b > a:
                return 0
            return fact[a] * invfact[b] % MOD * invfact[a-b] % MOD

        ans = 0
        for k in range(1, min(n, x) + 1):
            ways_assign = comb(x, k) * fact[k] % MOD * S[n][k] % MOD
            ans = (ans + ways_assign * pow(y, k, MOD)) % MOD
        return ans
