        v = int(next(it)) - 1
        adj[u].append(v)
        adj[v].append(u)
        deg[u] += 1
        deg[v] += 1

    # nodes that can be in a cycle: deg == 2 (endpoints) or deg == 3 (internal)
    good = [d == 2 or d == 3 for d in deg]
    visited = [False] * n
    ans = 0

    for start in range(n):
        if not good[start] or visited[start]:
            continue
        # traverse this component
        stack = [start]
        comp_nodes = []
        while stack:
            u = stack.pop()
            if visited[u]:
                continue
            visited[u] = True
            comp_nodes.append(u)
            for v in adj[u]:
                if good[v] and not visited[v]:
                    stack.append(v)

        # compute component degrees within component
        comp_deg = {}
        for u in comp_nodes:
            cnt = 0
            for v in adj[u]:
                if good[v]:
                    cnt += 1
            comp_deg[u] = cnt

        # if any node has component degree > 2, this component cannot form a simple path
        if any(cnt > 2 for cnt in comp_deg.values()):
            continue

        # count deg-2 nodes (possible cycle vertices)
        k = sum(1 for u in comp_nodes if deg[u] == 2)
        if k >= 2:
            ans += k * (k - 1) // 2

    print(ans)

