class Solution:
    def maxCollectedFruits(self, fruits):
        # This problem is equivalent to the classic "three paths to the bottom-right corner"
        # with each child allowed to move down, right, or diagonally.
        # A correct solution requires a dynamic programming approach over
        # the positions of all three children. Because of the symmetry of the moves,
        # the third child's position is uniquely determined by the other two
        # when all have taken the same number of steps.
        # The following implementation follows that observation and uses a
        # 2‑D DP table for each diagonal level to avoid O(n^4) complexity.
        n = len(fruits)
        dp = [[-1] * n for _ in range(n)]
        dp[0][0] = fruits[0][0]
        for k in range(1, 2 * n - 1):
            ndp = [[-1] * n for _ in range(n)]
            for i in range(max(0, k - (n - 1)), min(n, k + 1)):
                for j in range(max(0, k - (n - 1)), min(n, k + 1)):
                    best = -1
                    for di in (0, 1):
                        for dj in (0, 1):
                            pi, pj = i - di, j - dj
                            if pi >= 0 and pj >= 0 and dp[pi][pj] != -1:
                                best = max(best, dp[pi][pj])
                    if best == -1:
                        continue
                    r = k - i
                    c = k - j
                    if r < 0 or r >= n or c < 0 or c >= n:
                        continue
                    val = best + fruits[r][c]
                    if i == j and r == c:
                        val -= fruits[r][c]
                    ndp[i][j] = max(ndp[i][j], val)
            dp = ndp
        return max(max(row) for row in dp)
