        if s == t:
            continue
        if s not in mapping:
            mapping[s] = t
        elif mapping[s] != t:
            print(-1)
            return

    # Build graph for SCC detection
    graph = {}
    for s, t in mapping.items():
        graph.setdefault(s, set()).add(t)

    # Tarjan SCC
    index = 0
    stack = []
    indices = {}
    lowlink = {}
    onstack = set()
    scc_count = 0

    def strongconnect(v):
        nonlocal index, scc_count
        indices[v] = lowlink[v] = index
        index += 1
        stack.append(v)
        onstack.add(v)
        for w in graph.get(v, []):
            if w not in indices:
                strongconnect(w)
                lowlink[v] = min(lowlink[v], lowlink[w])
            elif w in onstack:
                lowlink[v] = min(lowlink[v], indices[w])
        if lowlink[v] == indices[v]:
            # found SCC
            scc_size = 0
            while True:
                w = stack.pop()
                onstack.remove(w)
                scc_size += 1
                if w == v:
                    break
            if scc_size > 1:
                nonlocal_cycles[0] += 1
            scc_count += 1

    nonlocal_cycles = [0]
    for v in graph:
        if v not in indices:
            strongconnect(v)

    edges = len(mapping)
    ans = edges + nonlocal_cycles[0]
    print(ans)

if __name__ == "__main__":
