class Solution:
    def lenOfVDiagonal(self, grid):
        n, m = len(grid), len(grid[0])
        # directions: (dr,dc)
        dirs = [(1,1),(-1,-1),(1,-1),(-1,1)]
        # dp[d][i][j]: length starting at (i,j) going in dir d following pattern
        dp = [[[0]*m for _ in range(n)] for _ in range(4)]
        # compute for each direction
        for d,(dr,dc) in enumerate(dirs):
            # order depends on direction to avoid dependency
            rows = range(n-1,-1,-1) if dr<0 else range(n)
            cols = range(m-1,-1,-1) if dc<0 else range(m)
            for i in rows:
                for j in cols:
                    v = grid[i][j]
                    if v==1:
                        nxt = 2
                    else:
                        nxt = 2 if v==2 else 0
                    ni, nj = i+dr, j+dc
                    if 0<=ni<n and 0<=nj<m and grid[ni][nj]==nxt:
                        dp[d][i][j] = 1 + dp[d][ni][nj]
                    else:
                        dp[d][i][j] = 1 if v==1 else 0
        best = 0
        # check each cell as possible turn or single
        for i in range(n):
            for j in range(m):
                if grid[i][j]==1:
                    best = max(best,1)
                for d1 in range(4):
                    l1 = dp[d1][i][j]
                    if l1==0: continue
                    # next direction after 90 clockwise
                    for d2 in [(d1+1)%4,(d1+3)%4]:
                        # turn point is at (i,j) after l1 steps includes start
                        # start next segment at previous cell in d2 direction
