import sys

def mat_mul(A, B, mod):
    n = len(A)
    m = len(B[0])
    k = len(B)
    res = [[0] * m for _ in range(n)]
    for i in range(n):
        Ai = A[i]
        for t in range(k):
            a = Ai[t]
            if a == 0:
                continue
            Bt = B[t]
            for j in range(m):
                res[i][j] = (res[i][j] + a * Bt[j]) % mod
    return res

def mat_pow(mat, exp, mod):
    n = len(mat)
    # identity matrix
    res = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
    base = [row[:] for row in mat]
    while exp:
        if exp & 1:
            res = mat_mul(res, base, mod)
        base = mat_mul(base, base, mod)
        exp >>= 1
    return res

