import sys

MOD = 998244353
G = 3

def ntt(a, invert):
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]
    length = 2
    while length <= n:
        wlen = pow(G, (MOD - 1) // length, MOD)
        if invert:
            wlen = pow(wlen, MOD - 2, MOD)
        for i in range(0, n, length):
            w = 1
            for j in range(i, i + length // 2):
                u = a[j]
                v = a[j + length // 2] * w % MOD
                a[j] = (u + v) % MOD
                a[j + length // 2] = (u - v) % MOD
                w = w * wlen % MOD
        length <<= 1
    if invert:
        inv_n = pow(n, MOD - 2, MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % MOD

def multiply(a, b):
    n = 1
    while n < len(a) + len(b) - 1:
        n <<= 1
    fa = a + [0] * (n - len(a))
    fb = b + [0] * (n - len(b))
    ntt(fa, False)
    ntt(fb, False)
    for i in range(n):
        fa[i] = fa[i] * fb[i] % MOD
    ntt(fa, True)
    return fa[:len(a) + len(b) - 1]

def poly_pow(base, exp, limit):
    res = [1]
    while exp:
        if exp & 1:
            res = multiply(res, base)
            if len(res) > limit + 1:
                res = res[:limit + 1]
        exp >>= 1
        if exp:
            base = multiply(base, base)
            if len(base) > limit + 1:
                base = base[:limit + 1]
    return res

def solve():
    data = sys.stdin.read().strip()
    if not data:
        return
    N = int(data)

    # Count numbers by length
    cnt = [0] * 7  # lengths 1..6
    for i in range(1, N + 1):
        l = len(str(i))
        cnt[l] += 1

    max_len = N
    poly = [1]
    for l in range(1, 7):
        if cnt[l] == 0:
            continue
        a = pow(10, l, MOD)
        base = [1, a]
        part = poly_pow(base, cnt[l], max_len)
        poly = multiply(poly, part)
        if len(poly) > max_len + 1:
            poly = poly[:max_len + 1]

    # factorials
    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % MOD

    # sum over k
    s = 0
    for k in range(0, N):
        if k >= len(poly):
            break
        term = fact[k] * fact[N - 1 - k] % MOD
        term = term * poly[k] % MOD
        s = (s + term) % MOD

    sum_j = N * (N + 1) // 2 % MOD
    ans = sum_j * s % MOD
    print(ans)

if __name__ == "__main__":
    solve()

