def comb(n: int, k: int, fact, invfact):
    if k < 0 or k > n or n < 0:
        return 0
    return fact[n] * invfact[k] % MOD * invfact[n - k] % MOD

def count_remaining(L: int, s: int, fact, invfact):
    """Number of Lukasiewicz words of length L that start from balance s
    and finish at -1 without dropping below -1."""
    if s < -1:
        return 0
    if L == 0:
        return 1 if s == -1 else 0
    # Formula: (s+1)/(L+1) * C(2L + s, L)
    num = comb(2 * L + s, L, fact, invfact)
    num = num * (s + 1) % MOD
    num = num * modinv(L + 1) % MOD
    return num

