def prefix_xor(arr):
    res = []
    s = 0
    for v in arr:
        s ^= v
        res.append(s)
    return res

def solve():
    N, M = readints()
    seqs = [readints() for _ in range(N)]
    # Precompute T^x for each sequence until all zeros
    tseqs = []
    max_len = 0
    for a in seqs:
        cur = a[:]
        steps = [cur]
        while any(cur):
            cur = prefix_xor(cur)
            steps.append(cur)
        tseqs.append(steps)
        max_len = max(max_len, len(steps))
    ans = 0
