            steps_i = tseqs[i]
            steps_j = tseqs[j]
            lim = min(len(steps_i), len(steps_j))
            f = -1
            for x in range(lim):
                if steps_i[x] == steps_j[x]:
                    f = x
                    break
            if f == -1:
                # if one finishes earlier, compare zeros
                f = lim
            ans = (ans + f) % MOD
    print(ans)

