    MOD = 10**9+7
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        n_bits = len(s)
        max_ones = n_bits  # maximum popcount for numbers < 2^n_bits

        # Precompute factorials and inverse factorials
        fact = [1]*(max_ones+1)
        for i in range(1, max_ones+1):
            fact[i] = fact[i-1]*i%self.MOD
        invfact = [1]*(max_ones+1)
        invfact[max_ones] = pow(fact[max_ones], self.MOD-2, self.MOD)
        for i in range(max_ones,0,-1):
            invfact[i-1] = invfact[i]*i%self.MOD

        def comb(n,r):
            if r<0 or r>n: return 0
            return fact[n]*invfact[r]%self.MOD*invfact[n-r]%self.MOD

        # Count numbers < n with popcount = c
        def count_with_popcount(c):
            cnt = 0
            ones_so_far = 0
            for i,ch in enumerate(s):
                if ch=='1':
                    rem = n_bits - i -1
                    cnt = (cnt + comb(rem, c - ones_so_far))%self.MOD
                    ones_so_far +=1
                # if ch=='0', nothing
            # exclude n itself if it has popcount==c
            if ones_so_far==c:
                cnt = (cnt -1)%self.MOD
            return cnt

        # Precompute reducibility for small c
        reducible_small = [0]*(max_ones+1)
        for c in range(1, max_ones+1):
            steps = 0
            x = c
            while x!=1 and steps<k:
                x = bin(x).count('1')
                steps+=1
            if x==1 and steps<=k-1:
                reducible_small[c]=1

        # Sum over c
        ans = 0
        for c in range(1, max_ones+1):
            if reducible_small[c]:
                ans = (ans + count_with_popcount(c))%self.MOD
        return ans

