class Solution:
    MOD = 10**9 + 7

    def countKReducibleNumbers(self, s: str, k: int) -> int:
        n_bits = len(s)
        # precompute k-reducible popcounts up to n_bits
        reducible = [False] * (n_bits + 1)
        for p in range(1, n_bits + 1):
            val, steps = p, 0
            while steps <= k:
                if val == 1:
                    reducible[p] = True
                    break
                if steps == k:
                    break
                val = bin(val).count("1")
                steps += 1

        # DP for numbers <= n
        dp_tight = [0] * (n_bits + 1)  # counts for tight=1
        dp_loose = [0] * (n_bits + 1)  # counts for tight=0
        dp_tight[0] = 1

        for bit_char in s:
            bit = int(bit_char)
            new_tight = [0] * (n_bits + 1)
            new_loose = [0] * (n_bits + 1)

            # transitions from loose state
            for cnt in range(n_bits + 1):
                if dp_loose[cnt] == 0:
                    continue
                # put 0
                new_loose[cnt] = (new_loose[cnt] + dp_loose[cnt]) % self.MOD
                # put 1
                if cnt + 1 <= n_bits:
                    new_loose[cnt + 1] = (new_loose[cnt + 1] + dp_loose[cnt]) % self.MOD

            # transitions from tight state
            for cnt in range(n_bits + 1):
                if dp_tight[cnt] == 0:
                    continue
                # put 0 -> becomes loose
                new_loose[cnt] = (new_loose[cnt] + dp_tight[cnt]) % self.MOD
                # put 1 if allowed
                if bit == 1:
                    if cnt + 1 <= n_bits:
                        new_tight[cnt + 1] = (new_tight[cnt + 1] + dp_tight[cnt]) % self.MOD

            dp_tight, dp_loose = new_tight, new_loose

        # total count of numbers <= n with reducible popcount
        total = 0
        for cnt in range(1, n_bits + 1):
            if reducible[cnt]:
                total = (total + dp_tight[cnt] + dp_loose[cnt]) % self.MOD

        # subtract n itself if it is counted
        n_pop = s.count("1")
        if reducible[n_pop]:
            total = (total - 1) % self.MOD

